def compute_metric(orders, refunds):
    total_refund_rows = len(refunds)
    seen = {}
    duplicate_rows = 0
    for row in refunds:
        refund_id = row.get('refund_id')
        if refund_id in seen:
            duplicate_rows = duplicate_rows + 1
        else:
            seen.setdefault(refund_id, 1)
    if total_refund_rows == 0:
        replay_rate_bps = 0
    else:
        replay_rate_bps = (duplicate_rows * 10000) // total_refund_rows
    data = {
        'total_refund_rows': total_refund_rows,
        'duplicate_rows': duplicate_rows,
        'replay_rate_bps': replay_rate_bps
    }
    evidence = {
        'metric': 'refund_replay_rate',
        'definition': 'Count later occurrences of an exact refund_id in RAW rows; return total_refund_rows, duplicate_rows and floor(duplicate_rows*10000/total_refund_rows), or zero for empty input.',
        'input_view': 'raw',
        'note': 'Record replay only; never repeated real payments.'
    }
    return data, evidence
